contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will try to Put some ether from this contract into c, then attempt Collect.
    // Parameters:
    // - putAmount: amount of wei to send to c via Put
    // - lockTime: lock time argument to Put
    // - collectAmount: amount to attempt to Collect
    function run(uint putAmount, uint lockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient balance to fund Put");

        // Ensure MinSum is 0 so Collect won't be blocked by uninitialized MinSum
        // SetMinSum may only be called before Initialized(); call it here.
        // We don't care if it reverts; but we call it only if it won't revert: intitalized default false.
        c.SetMinSum(0);

        // Read balance and holder info before actions
        C.Holder memory before = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Put funds into c for this contract
        c.Put{value: putAmount}(lockTime);

        // Read post-Put holder state
        C.Holder memory afterPut = c.Acc(address(this));
        uint afterPutContractBal = address(c).balance;

        // Now attempt Collect; it may revert. Capture whether it reverted.
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read holder state after Collect attempt
        C.Holder memory after = c.Acc(address(this));
        uint afterContractBal2 = address(c).balance;

        // Assert general property:
        // If Collect did NOT revert, then (1) the holder's balance decreased by exactly collectAmount,
        // and (2) the contract's ether balance decreased by at least collectAmount (it may be equal).
        // We express decrease comparisons using >= to avoid underflow in the assert.
        assert(
            reverted || (
                after.balance + collectAmount == afterPut.balance
                && afterPutContractBal >= afterContractBal2
                && (afterPutContractBal - afterContractBal2) >= collectAmount
            )
        );
    }

    // Allow this test contract to receive ether for funding Put
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters:
    // putAmount: wei to send to c.Put
    // lockTime: lock time for Put
    // collectAmount: amount to attempt to Collect
    function run(uint putAmount, uint lockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient balance to fund Put");

        // Ensure MinSum is zero so Collect is not blocked by MinSum (SetMinSum only callable before Initialized)
        // We call it and ignore any potential revert by letting it propagate if it would (it shouldn't since intitalized is false on fresh c).
        c.SetMinSum(0);

        // Read holder state before Put
        (uint beforeUnlock, uint beforeBalance) = _readHolder(address(this));
        uint beforeContractBal = address(c).balance;

        // Put funds into c
        c.Put{value: putAmount}(lockTime);

        // Read holder state after Put
        (uint afterPutUnlock, uint afterPutBalance) = _readHolder(address(this));
        uint afterPutContractBal = address(c).balance;

        // Attempt Collect and capture revert status
        bool reverted;
        try c.Collect(callAmountOrZero(collectAmount)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read holder state after Collect attempt
        (uint finalUnlock, uint finalBalance) = _readHolder(address(this));
        uint finalContractBal = address(c).balance;

        // If Collect did not revert then holder.balance decreased by exactly collectAmount
        // and the contract's balance decreased by at least collectAmount.
        assert(
            reverted || (
                // finalBalance + collectAmount == afterPutBalance
                finalBalance + collectAmount == afterPutBalance
                && afterPutContractBal >= finalContractBal
                && (afterPutContractBal - finalContractBal) >= collectAmount
            )
        );
    }

    // helper to read the public Acc mapping (auto-generated getter has signature Acc(address) returns (uint unlockTime, uint balance))
    function _readHolder(address who) internal returns (uint, uint) {
        (uint u, uint b) = c.Acc(who);
        return (u, b);
    }

    // helper to make the Collect call use a valid uint when used in try (keeps syntax simple)
    function callAmountOrZero(uint a) internal pure returns (uint) { return a; }

    receive() external payable {}
}

