        } catch {
            putReverted = true;
        }

        // read intermediate values
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // 3) attempt Collect for collectAmount and record whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General invariant to assert:
        // - If Put reverted then balances and contract balance unchanged after Put and Collect may only succeed if nothing changed (but Collect cannot succeed because funds weren't added); we express conservative combined rule as follows.
        // - If Put succeeded and Collect succeeded then holder balance decreased by exactly collectAmount and contract balance decreased by exactly collectAmount.
        // - In all other cases (any revert in Put or Collect) the holder balance and contract balance did not both decrease by collectAmount.

        assert(
            // Case where both Put and Collect succeeded: exact decreases of collectAmount
            (!putReverted && !collectReverted) ? (
                afterBalance + collectAmount == midBalance && afterContractBal + collectAmount == midContractBal
            ) : (
                // Otherwise, it's not true that both holder and contract balances decreased by collectAmount from mid to after.
                !(midBalance >= collectAmount && afterBalance + collectAmount == midBalance && midContractBal >= collectAmount && afterContractBal + collectAmount == midContractBal)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function driving C. We avoid calling Put to prevent hitting add_uint256 in P;
    // instead rely on externally set state via MinSum/LogFile/Initialized and then call Collect which
    // must either revert or, if it succeeds, transfer funds consistently.
    function run(uint collectAmount, uint minSum, address logAddr) public payable {
        // No requirement on this contract balance because we won't call Put; Collect should not require sending value.

        // Ensure contract is initialized so SetMinSum/SetLogFile can be called once each without revert.
        // These calls may revert if intitalized is already true, but since c is fresh they should succeed.
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // read holder and contract balances before Collect
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // attempt Collect and record whether it reverted
        bool collectReverted = true;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read after state
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Assert the general rule: if Collect succeeded then both the holder balance and contract balance
        // decreased by exactly collectAmount; otherwise (if Collect reverted) no relation is required.
        // Avoid underflow in the assert by using >= checks before doing subtraction-equality.
        assert(
            collectReverted || (
                beforeBalance >= collectAmount && beforeContractBal >= collectAmount &&
                afterBalance + collectAmount == beforeBalance && afterContractBal + collectAmount == beforeContractBal
            )
        );
    }

    receive() external payable {}
}

